"""StudyHarness — runner for the pre-registered Monte-Carlo study (plan Phase 2b).

Executes a factorial grid (variant x k x seed x method) of synthetic cases
through the unmodified vlinder pipeline and writes one tidy results row per
case x scenario x method — the canonical results store every downstream table
and figure reads from (single source of truth).

Design decisions (documented for the methodology chapter):
  * Cases are generated by ``SyntheticCaseFactory`` (byte-reproducible from the
    seed) and certified by ``oracle.certify_case`` before any method runs; the
    certificate is cached in the case manifest, so re-runs never re-solve it.
  * Checkpointing: every completed task is appended to ``results.jsonl``
    immediately. On resume, completed (case, scenario, method) keys are
    skipped, so an interrupted study continues where it stopped.
  * Runtime cap (pre-registration section 3): recorded as a ``censored`` flag on
    the row (wall time above the cap). vlinder's grid search self-bounds its
    evaluation count via ``max_combinations`` (the step size coarsens instead
    of the runtime exploding), so the cap flags rather than kills; the quality
    loss H2 predicts shows up in the gap metric, the cost in evals/runtime.
  * ``method_seed`` equals the case seed — deterministic, recorded, and immune
    to seed-shopping.
  * Environment (python/numpy/scipy/vlinder commit) is written to ``meta.json``
    next to the results, per pre-registration section 6.

Run the dry-run validation (plan Phase 2 definition-of-done):
  & "C:\\Users\\joepw\\.virtualenvs\\tRBS-DclBJWVi-python.exe\\Scripts\\python.exe" `
    experiments/synthetic/study_harness.py --dry-run
"""

# pylint: disable=too-many-locals

import json
import platform
import subprocess
import sys
import time
from concurrent.futures import ProcessPoolExecutor, as_completed
from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import scipy

from case_factory import SyntheticCaseFactory, SyntheticCaseParams, read_manifest
from oracle import certify_case

from vlinder.trbs import TheResponsibleBusinessSimulator
from vlinder.utils import suppress_print

#: Frozen per-method defaults — mirror pre-registration v1.1 section 2.
METHOD_DEFAULTS = {
    "grid": {"max_combinations": 60000},
    "slsqp": {"n_starts": 100},
    "basin_hopping": {"n_hops": 25, "n_starts": 1},
    "genetic_algorithm": {"population_size": 50, "n_generations": 60},
}


@dataclass
class StudySpec:
    """Factorial design of one study run (defaults = the confirmatory H1/H2 grid)."""

    variants: tuple = ("linear", "sinusoidal")
    ks: tuple = (2, 3, 4, 6, 9, 12, 15)
    seeds: tuple = tuple(range(30))
    methods: tuple = ("grid", "slsqp", "basin_hopping", "genetic_algorithm")
    method_kwargs: dict = field(default_factory=dict)  # per-method overrides of METHOD_DEFAULTS
    runtime_cap_s: float = 600.0
    recovery_eps: float = 0.1
    root: str = str(Path(__file__).parent / "generated" / "study")

    @staticmethod
    def n_key_outputs(k):
        """Pre-registration section 2: n_key_outputs = max(2, min(5, (k+1)//2))."""
        return max(2, min(5, (k + 1) // 2))

    def case_name(self, variant, k, seed):
        """Deterministic case naming: Study_<variant>_k<k>_s<seed>."""
        return f"Study_{variant}_k{k:02d}_s{seed}"


class StudyHarness:
    """Generates, certifies and runs the factorial study with checkpoint/resume."""

    def __init__(self, spec: StudySpec):
        self.spec = spec
        self.root = Path(spec.root)
        self.root.mkdir(parents=True, exist_ok=True)
        self.results_path = self.root / "results.jsonl"
        self.meta_path = self.root / "meta.json"

    # ---------------- case preparation ----------------
    def ensure_case(self, variant, k, seed):
        """Generate + oracle-certify one case (idempotent); return its manifest."""
        name = self.spec.case_name(variant, k, seed)
        manifest = read_manifest(name, self.root)
        if manifest is None:
            params = SyntheticCaseParams(
                name=name,
                k=k,
                n_key_outputs=self.spec.n_key_outputs(k),
                seed=seed,
                appreciation=variant,
            )
            SyntheticCaseFactory(params).write(self.root)
            manifest = read_manifest(name, self.root)
        if manifest.get("oracle") is None:
            certify_case(name, self.root)
            manifest = read_manifest(name, self.root)
        return name, manifest

    # ---------------- task list & bookkeeping ----------------
    @staticmethod
    def task_key(name, scenario, method):
        """Resume key of one results row."""
        return f"{name}|{scenario}|{method}"

    def completed_keys(self):
        """Keys already present in results.jsonl (crash-safe resume)."""
        done = set()
        if self.results_path.exists():
            with open(self.results_path, encoding="utf-8") as fh:
                for line in fh:
                    if line.strip():
                        row = json.loads(line)
                        done.add(self.task_key(row["case_name"], row["scenario"], row["method"]))
        return done

    def build_tasks(self):
        """Generate/certify all cases, then enumerate the not-yet-done tasks."""
        done = self.completed_keys()
        tasks = []
        for variant in self.spec.variants:
            for k in self.spec.ks:
                for seed in self.spec.seeds:
                    name, manifest = self.ensure_case(variant, k, seed)
                    tasks.extend(self._case_tasks(name, manifest, done))
        return tasks

    def _case_tasks(self, name, manifest, done):
        """Enumerate the not-yet-done (scenario, method) tasks of one case."""
        k = int(manifest["params"]["k"])
        seed = int(manifest["seed"])
        budget = float(manifest["params"]["budget"])
        oracle = manifest["oracle"]
        tasks = []
        for scenario, cert in oracle["per_scenario"].items():
            for method in self.spec.methods:
                if self.task_key(name, scenario, method) in done:
                    continue
                kwargs = dict(METHOD_DEFAULTS.get(method, {}))
                kwargs.update(self.spec.method_kwargs.get(method, {}))
                tasks.append(
                    {
                        "root": str(self.root),
                        "case_name": name,
                        "regime": manifest["regime"],
                        "variant": manifest["appreciation"],
                        "k": k,
                        "case_seed": seed,
                        "scenario": scenario,
                        "method": method,
                        "method_kwargs": kwargs,
                        "method_seed": seed,
                        "budget": budget,
                        "f_oracle": float(cert["f_star"]),
                        "oracle_verified": bool(oracle.get("verified", False)),
                        "recovery_eps": self.spec.recovery_eps,
                        "runtime_cap_s": self.spec.runtime_cap_s,
                    }
                )
        return tasks

    # ---------------- execution ----------------
    @staticmethod
    def run_task(task):
        """Run ONE (case, scenario, method) cell through the real pipeline.

        Static and picklable so it can run in worker processes on Windows.
        """

        @suppress_print
        def _build():
            sim = TheResponsibleBusinessSimulator(
                task["case_name"], file_path=Path(task["root"]), file_extension="csv"
            )
            sim.build()
            sim.evaluate()
            sim.appreciate()
            return sim

        sim = _build()
        t0 = time.perf_counter()
        result = sim.optimize(
            task["scenario"],
            method=task["method"],
            dmo_name=f"Study ({task['method']})",
            seed=task["method_seed"],
            **task["method_kwargs"],
        )
        wall = time.perf_counter() - t0
        gap = task["f_oracle"] - float(result.appreciation)
        return {
            "case_name": task["case_name"],
            "regime": task["regime"],
            "variant": task["variant"],
            "k": task["k"],
            "case_seed": task["case_seed"],
            "scenario": task["scenario"],
            "method": task["method"],
            "method_seed": task["method_seed"],
            "f_found": float(result.appreciation),
            "f_oracle": task["f_oracle"],
            "gap": gap,
            "recovered": bool(gap <= task["recovery_eps"]),
            "oracle_verified": task["oracle_verified"],
            "allocation": np.asarray(result.allocation).tolist(),
            "spend_fraction": float(np.sum(result.allocation) / task["budget"]),
            "n_function_evals": result.n_function_evals,
            "wall_time_s": wall,
            "censored": bool(wall > task["runtime_cap_s"]),
            "timestamp": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        }

    def write_meta(self):
        """Record the environment + spec next to the results (pre-reg section 6)."""
        try:
            commit = subprocess.run(
                ["git", "rev-parse", "HEAD"], capture_output=True, text=True, check=True, cwd=Path(__file__).parent
            ).stdout.strip()
        except (OSError, subprocess.CalledProcessError):
            commit = "unknown"
        meta = {
            "python": sys.version.split()[0],
            "numpy": np.__version__,
            "scipy": scipy.__version__,
            "platform": platform.platform(),
            "vlinder_commit": commit,
            "method_defaults": METHOD_DEFAULTS,
            "spec": asdict(self.spec),
            "written": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        }
        self.meta_path.write_text(json.dumps(meta, indent=2), encoding="utf-8")

    def run(self, n_workers=1):
        """Execute all remaining tasks; append each finished row to results.jsonl."""
        self.write_meta()
        tasks = self.build_tasks()
        print(f"[harness] {len(tasks)} tasks to run ({len(self.completed_keys())} already done)")
        with open(self.results_path, "a", encoding="utf-8") as out:
            if n_workers <= 1:
                for i, task in enumerate(tasks):
                    row = self.run_task(task)
                    out.write(json.dumps(row) + "\n")
                    out.flush()
                    print(
                        f"[harness] {i + 1}/{len(tasks)} {row['case_name']} {row['scenario']} "
                        f"{row['method']}: gap={row['gap']:.2e} ({row['wall_time_s']:.1f}s)"
                    )
            else:
                with ProcessPoolExecutor(max_workers=n_workers) as pool:
                    futures = {pool.submit(StudyHarness.run_task, t): t for t in tasks}
                    for i, fut in enumerate(as_completed(futures)):
                        row = fut.result()
                        out.write(json.dumps(row) + "\n")
                        out.flush()
                        print(
                            f"[harness] {i + 1}/{len(tasks)} {row['case_name']} {row['scenario']} "
                            f"{row['method']}: gap={row['gap']:.2e} ({row['wall_time_s']:.1f}s)"
                        )
        return self.export_csv()

    def export_csv(self):
        """Flatten results.jsonl to results.csv (allocation JSON-encoded)."""
        import pandas as pd  # pylint: disable=import-outside-toplevel

        rows = []
        with open(self.results_path, encoding="utf-8") as fh:
            for line in fh:
                if line.strip():
                    rows.append(json.loads(line))
        frame = pd.DataFrame(rows)
        if not frame.empty:
            frame["allocation"] = frame["allocation"].apply(json.dumps)
        csv_path = self.root / "results.csv"
        frame.to_csv(csv_path, index=False)
        return csv_path


def dry_run():
    """Phase-2 definition-of-done: a tiny grid must reproduce the Phase-1
    acceptance gaps (0.0 on linear, <= ~1e-4 on curved) and resume cleanly."""
    spec = StudySpec(
        variants=("linear", "sinusoidal"),
        ks=(2, 3),
        seeds=(0, 1),
        methods=("slsqp",),
        root=str(Path(__file__).parent / "generated" / "dryrun"),
    )
    harness = StudyHarness(spec)
    csv_path = harness.run(n_workers=1)

    with open(harness.results_path, encoding="utf-8") as fh:
        rows = [json.loads(line) for line in fh if line.strip()]
    linear = [r["gap"] for r in rows if r["variant"] == "linear"]
    curved = [r["gap"] for r in rows if r["variant"] == "sinusoidal"]
    print(
        f"[dry-run] rows={len(rows)}  linear max|gap|={max(abs(g) for g in linear):.2e}  "
        f"curved max|gap|={max(abs(g) for g in curved):.2e}"
    )
    assert len(rows) == 24, f"expected 24 rows (8 cases x 3 scenarios x 1 method), got {len(rows)}"
    assert max(abs(g) for g in linear) <= 1e-6, "linear regime must reproduce gap 0.0 (Phase-1 acceptance)"
    assert max(abs(g) for g in curved) <= 1e-3, "curved regime gaps must stay at Phase-1 acceptance level"

    # Resume check: a second run must find nothing left to do.
    leftover = harness.build_tasks()
    assert not leftover, f"resume failed: {len(leftover)} tasks re-queued after completion"
    print(f"[dry-run] PASS — results at {csv_path}, resume check clean")


if __name__ == "__main__":
    if "--dry-run" in sys.argv:
        dry_run()
    else:
        print("Confirmatory grid runs only after the pre-registration lock (plan Phase 2a).")
        print("Use --dry-run for the Phase-2 validation grid.")
